// Mesma validacao do cenario A: so grava JSON. HTML com status 200 (BCB) ou corpo vazio vira erro.
const c = $('Recebe a chamada').first().json;
const r = $json;
const tipo = String(r.headers?.['content-type'] ?? '');
const vazio = r.body === undefined || r.body === null || r.body === '' ||
              (Array.isArray(r.body) && r.body.length === 0);
if (c.fonte === 'BCB' && (r.statusCode === 404 || vazio)) {
  return [{ json: { gravar: false, resultado: 'nada_novo' } }];
}
if (!tipo.toLowerCase().includes('json') || typeof r.body !== 'object' || vazio) {
  return [{ json: { gravar: false, resultado: 'erro',
                    mensagem: `resposta invalida (HTTP ${r.statusCode}, content-type ${tipo || 'vazio'})` } }];
}
return [{ json: { gravar: true, http_status: r.statusCode, payload: r.body } }];

const c = $('Recebe a chamada').first().json;
const nova = Boolean($json.resposta_id);
return [{ json: { execucao_id: c.execucao_id, recurso: c.recurso, lote: c.lote,
                  resultado: nova ? 'nova' : 'ja_existia', http_status: 200 } }];

const c = $('Recebe a chamada').first().json;
return [{ json: { execucao_id: c.execucao_id, recurso: c.recurso, lote: c.lote,
                  resultado: $json.resultado, mensagem: $json.mensagem ?? null } }];

// HTTP com erro depois das 3 tentativas, ou INSERT com erro.
const c = $('Recebe a chamada').first().json;
const e = $json.error ?? $json;
const texto = typeof e === 'string' ? e : (e.message ?? JSON.stringify(e));
// BCB: 404 = "nada novo" (nao e erro)
if (c.fonte === 'BCB' && /404/.test(texto)) {
  return [{ json: { execucao_id: c.execucao_id, recurso: c.recurso, lote: c.lote, resultado: 'nada_novo' } }];
}
return [{ json: { execucao_id: c.execucao_id, recurso: c.recurso, lote: c.lote,
                  resultado: 'erro', mensagem: String(texto).slice(0, 300) } }];
